// Helper function to calculate the score for a given boring apartment number
#[verus]
fn score(x: i32) -> i32 {
    let d = x / 1111; // Extract the digit
    let k = (x.to_string().len() as i32); // Extract the length

    // Calculate the score for all boring apartment numbers up to x
    let mut total_score: i32 = 0;

    for digit in 1..=d {
        for length in 1..=4 {
            total_score += length; // Each number contributes its length to the score
            if digit * 1111 / 1111 == x && length == k {
                return total_score; // Return the score when we reach x
            }
        }
    }

    total_score
}